`,instagram:"https://www.instagram.com/produzioniattualita/",servizi:[{h:"Reel di notizia",p:"Un video per ogni articolo, pronto per Instagram, TikTok, Facebook e YouTube Shorts."},{h:"Montaggio video",p:"Ci mandate i vostri filmati, li trasformiamo in video notizie pronte da pubblicare, con titoli, grafiche e sottotitoli."},{h:"TG",p:"Le notizie del giorno raccolte in un'unica edizione, con la sigla e i banner della vostra testata."},{h:"Rubrica meteo",p:"Le previsioni della settimana in un appuntamento fisso, con il vostro conduttore."},{h:"Interviste e approfondimenti",p:"Un ospite, un tema, le domande giuste: montati e pronti da pubblicare."}],passi:[{h:"Ci mandate la notizia",p:"L'articolo, oppure pi\xF9 articoli per il TG."},{h:"La trasformiamo in video",p:"Scriviamo il testo, verifichiamo i dati e realizziamo voce, video e grafiche."},{h:"La pubblicate",p:"Ricevete il video pronto, nei formati giusti per ogni social."}],suMisura:{h:"Il vostro marchio in primo piano",p:"Un conduttore virtuale dedicato, con le grafiche, la sigla e i colori della vostra testata. Il vostro marchio resta in primo piano, noi lavoriamo dietro le quinte.",punti:["Conduttore virtuale dedicato","Grafiche e colori della testata","Sigla e banner su misura","Formati per ogni social"]},perche:{h:"Perch\xE9 noi",p:"Produciamo ogni giorno i video di Iattualit\xE0, testata indipendente verificata con i dati. Lo stesso metodo lo mettiamo al servizio della vostra redazione."},prezzi:{h:"Quanto costa",p:"Ogni testata ha esigenze diverse: prepariamo un preventivo su misura in base a quanti video vi servono e a quali formati.",prova:{h:"Prova di 15 giorni",p:"Per 15 giorni ricevete i video come se foste gi\xE0 clienti e li pubblicate sui vostri canali. Poi decidete se continuare."}},faq:[{q:"Quanto durano i video?",a:"Decidete voi: adattiamo durata e ritmo alla vostra testata e ai social dove pubblicate."},{q:"In quanto tempo arriva un video?",a:"Lo concordiamo con voi, in base a quanti video vi servono e a quando volete pubblicarli."},{q:"Possiamo mandarvi i nostri filmati?",a:"S\xEC: se avete immagini e video vostri li montiamo nel servizio, altrimenti alle immagini pensiamo noi."},{q:"Lavorate anche su notizie locali?",a:"S\xEC: partiamo dagli articoli che ci mandate, qualunque sia il territorio che raccontate."},{q:"Il conduttore \xE8 una persona reale?",a:"\xC8 un conduttore virtuale, realizzato con l'intelligenza artificiale e personalizzato per voi. Testi, verifica dei dati e scelte editoriali restano umani."},{q:"Di chi sono i video?",a:"Sono realizzati per la vostra testata e pubblicati sui vostri canali. Le condizioni d'uso le mettiamo nero su bianco nel preventivo."}]};function ui(){return"mailto:"+Ue.email+"?subject="+encodeURIComponent(Ue.oggetto)+"&body="+encodeURIComponent(Ue.corpo)}function zo(e){let i=e.split(/\n+/).map(a=>a.trim()).filter(Boolean),o=[],n="";for(let a of i)n=n?n+" "+a:a,/[.!?…:»"”)]$/.test(a)&&(o.push(n),n="");return n&&o.push(n),o.join(`
